(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sr"] = {"ui":{"skip":"Пређи на садржај","back":"← Назад на AI-gile","lang.button":"Језик: {name}","lang.dialog":"Изабери језик","lang.search":"Претражи језике","lang.none":"Ниједан језик не одговара","lang.notYet":"{name} још није преведен","theme.aria":"Пребаци између светле и тамне теме","theme.toLight":"Пређи на светлу тему","theme.toDark":"Пређи на тамну тему","index.title":"AI-gile: твој AI тим програмера на једној табли","index.description":"AI-gile је канбан табла за AI тимове који пишу код. Они раде док ти спаваш; ти добијеш једну кратку гомилу ствари да одлучиш, тестираш и прихватиш.","hero.logoAlt":"Икона AI-gile табле","hero.h1.html":"Твој AI тим програмера на једној&nbsp;табли.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовршено: хвала што пробаш!","hero.lede":"Они граде док ти спаваш. Будиш се уз једну кратку гомилу: пар питања, пар ствари за тест, један или два љубичаста дијаманта. Кликни, прихвати, и назад на кафу.","dl.windows":"Windows апликација","dl.browser":"Покрени у прегледачу","dl.soon":"Ускоро","dl.notify":"🔔 Јави ми кад се отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Agile, али тиму никад не треба кафа за стендап. (Стендап ипак држе.)","pitch.h2":"AI-gile у онолико речи колико хоћеш","pitch.lede":"Изабери дужину, од једне речи до 144. Свака дужина је посебан опис, написан баш за ту величину. Повуци клизач или користи стрелице.","pitch.rangeLabel":"Дужина у речима","pitch.dice":"🎲 друга верзија","pitch.words.one":"{n} реч","pitch.words.few":"{n} речи","pitch.words.other":"{n} речи","pitch.letters.one":"{n} слово","pitch.letters.few":"{n} слова","pitch.letters.other":"{n} слова","pitch.chars.one":"{n} знак","pitch.chars.few":"{n} знака","pitch.chars.other":"{n} знакова","count.line.html.one":"{n} картица на табли управо сад","count.line.html.few":"{n} картице на табли управо сад","count.line.html.other":"{n} картица на табли управо сад","features.aria":"Шта ради","f.pile.h":"Једна гомила за тебе","f.pile.html":"<b>За тебе</b> држи све што чека тебе, преко свих пројеката: питања, ствари за тест, задатке које може само човек. Твој ред каже шта је следеће и колико траје.","f.sleep.h":"Тимови који раде док ти спаваш","f.sleep.p":"Сваки пројекат има вођу и тим AI агената. Коментариши картицу и тим се буди, одради посао и врати је са корацима које може да прати и уморан човек.","f.tester.h":"AI тестер проверава први","f.tester.p":"Пре него што нешто стигне до тебе, тестер прати кораке у копији апликације и показује шта је видео, са снимком екрана. Прелистај оне који су прошли и прихвати једним кликом.","f.proof.h":"Докази, не обећања","f.proof.p":"Свака предаја показује шта се променило: фајлове, разлику, снимке екрана. Не мораш да отвараш сваку апликацију да видиш да ли је готово.","f.chat.h":"Ћаскај са својим вођама","f.chat.p":"Трака као на Discordu: једна икона по пројекту, љубичасти дијаманти за оно што треба тебе. Пошаљи вођи идеју; он је претвори у картице и план, са дугметом ✅ Крени.","f.tidy.h":"Сама се сређује","f.tidy.p":"Сродне картице се спајају у једну, збркани наслови се поправљају, а провера токена држи код сажетим. Мање ствари између којих се пребацујеш, мање мисли.","f.private.h":"Твоје, на твом рачунару","f.private.li1":"Табла ради на твом рачунару и одговара само теби.","f.private.li2":"Приватне поруке међу људима су шифроване од краја до краја.","f.private.li3":"Без налога, без трагача, без колачића.","f.lang.h":"На твом језику","f.lang.p":"Преко 120 језика, од холандског, велшког и јапанског до гусарског, Јоде и клингонског, уз брзи повратак на енглески за програмерске речи.","tl.aria":"Временска линија од првог разговора до плана","tl.h2":"Од првог ћаскања до онога што следи","tl.lede":"Прави датуми и сати, у твојој временској зони. После данас то је план, без обећаних датума.","tl.today":"Данас","tl.planned":"планирано","tl.cards.one":"{n} картица","tl.cards.few":"{n} картице","tl.cards.other":"{n} картица","join.h2":"Придружи се","join.lede":"AI-gile прави један мали човек и много стрпљивих агената. За сада је приватан, у затвореној алфи са пријатељима. Хоћеш да пробаш кад се отвори?","join.btn":"Пријави интересовање","join.small":"Послаћемо ти мејл, ништа друго","footer.tag":"AI-gile. Без трагача, без колачића, без кафе за стендап.","footer.licence":"Пословна лиценца","footer.status":"Статус","form.sending":"Шаље се…","form.failed":"Није успело: покушај поново касније.","form.offline":"Није могуће допрети до AI-gile: покушај поново касније.","interest.title":"AI-gile: јави ми кад се алфа отвори","interest.description":"Остави мејл да чујеш кад се отвори затворена алфа или бета AI-gile.","interest.h1":"🔔 Јави ми кад се отвори","interest.lede":"AI-gile је у затвореној пре-алфи. Остави мејл и јавићемо се једном, кад буде места за тебе.","interest.email":"Твој мејл","interest.which":"Који тест?","interest.alpha":"Затворена алфа: рано, грубо, пуно промена","interest.beta":"Бета: стабилнија, касније","interest.both":"Било која, шта прво дође","interest.submit":"Упиши ме на листу","interest.thanks":"Хвала! На листи си.","interest.kept":"Чувају се само твој мејл и тест који си изабрао, искључиво за ову листу. Без билтена, без трагача.","licence.title":"AI-gile: пословна лиценца","licence.description":"Користиш AI-gile у послу? Затражи бесплатну пословну лиценцу.","licence.h1":"📜 Пословна лиценца","licence.lede":"Користиш AI-gile на послу? Реци нам ко си и чиме се бавиш. Ако то чини нешто добро, лиценца је бесплатна.","licence.company":"Компанија","licence.website":"Веб-сајт","licence.what":"Чиме се бавиш","licence.how":"Како помаже свету","licence.email":"Мејл","licence.submit":"Пријави се","licence.thanks":"Хвала! Одговорићемо мејлом.","status.title":"AI-gile статус","status.h1":"AI-gile статус","status.quiet":"Све мирно","status.checking":"Проверавам…","status.offline":"Тренутно не могу да допрем до услуге статуса (покушавам поново)","status.updated":"ажурирано {ago}","status.justNow":"управо сад","status.min":"пре {n} мин","status.hours":"пре {n} ч","status.days":"пре {n} д","live.h2":"Гледајте како се гради, уживо","live.caption":"Свака картица је скривена: видите облик посла, а не речи.","live.watching.one":"уживо: {n} гледа","live.watching.other":"уживо: {n} гледа","live.offline":"Табла уживо мало одмара. Навратите ускоро.","live.cols":"Backlog|Треба урадити|У току|Тим проверава|Чека твој тест|За тим|Готово"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Канбан, аутоматизован.","Агенти, организовани.","Идеје, изграђене."]},{"n":3,"texts":["Канбан за роботе.","Идеје постају функције.","Бесплатан канбан агената."]},{"n":5,"texts":["Канбан табла коју воде агенти.","Ти пишеш картице. Агенти граде.","Бесплатно, локално, тестирано, помало смешно."]},{"n":8,"texts":["Бесплатна канбан табла на којој раде AI агенти.","Напиши идеју. Агенти је граде. Ти прихваташ.","Agile за једног човека и много стрпљивих робота."]},{"n":13,"texts":["Канбан табла на твом рачунару на којој AI агенти узимају картице и граде.","Напиши идеју. Тим агената је гради. Тестер је проверава, а ти одлучујеш.","Бесплатно, без налога и трагача: једна табла, пар робота и ти као шеф."]},{"n":21,"texts":["AI-gile је канбан табла за рад са AI агентима који пишу код. Они узимају картице; ти их тестираш и прихваташ.","Сваки пројекат добија вођу и тим AI агената. Коментариши било коју картицу и тим се хвата посла.","Бесплатна, лична табла задатака која ради на твом рачунару. Радници су роботи. Онај који каже да је ти."]},{"n":34,"texts":["Идеје стављаш на таблу. Тим AI агената од њих прави функције које раде, тестира их и враћа ти их са корацима за пробу. Ништа се не рачуна као готово док ти то не кажеш.","AI-gile је кућна канбан табла коју је Рич направио уз пуно помоћи агената којима сада управља. Бесплатна је, ради на твом рачунару и дели се са пријатељима, не продаје се.","Замисли обичну канбан таблу, са колонама од Backlog-а до Готово, само што картице узимају AI агенти. Јављају напредак, питају кад западну и увек сачекају твој палац горе."]},{"n":55,"texts":["AI-gile је канбан табла на којој тим чине AI агенти. Сваки пројекат има вођу који планира посао и помоћнике који граде. Кад је функција спремна, AI тестер је проба и направи снимак екрана, а онда стиже у твоју гомилу. Прихвати је, или коментариши па је раде поново.","Почело је као начин једне особе да прати много AI сесија кодирања одједном, а израсло је у праву таблу. Ради на твом рачунару, не тражи налог и нема трагача. Бесплатна је за пријатеље и радознале. Такође је недовршена, па очекуј грубе ивице и по неко изненађење.","Ево поштене верзије. И даље мораш сам да имаш идеје, и даље мораш сам да провериш резултате. Све између ради AI-gile: држи картице у реду, буди правог агента кад оставиш коментар, показује тачно шта се променило и све то сабира у једну кратку гомилу за тебе, па нема лутања од апликације до апликације."]},{"n":89,"texts":["AI-gile је бесплатна канбан табла коју покрећеш на свом рачунару. Уместо људи, сваки пројекат има тим AI агената: вођу који твоје идеје претвара у картице и план, и помоћнике који узимају картице по приоритету. Кад је нешто направљено, AI тестер прати кораке за тест и показује ти шта је видео. Затим чека у једној гомили која се зове За тебе. Прихватиш га, или коментаришеш и тим покушава поново. Ништа никад не стигне до Готово без тебе.","Неке ствари које можда не очекујеш. Ноћна стража допуњује колону Треба урадити док ти спаваш, бирајући картице којима не треба твој одговор. Бројач токена показује колико су агенти потрошили данас и ове недеље, а No Token Mode им каже да престану да троше. Можеш да пишеш пријатељима, а приватне поруке су шифроване од краја до краја. Табла говори око 120 језика, међу њима холандски, фламански, гусарски и клингонски. Ништа од тога не кошта ни динар, а ни ко ти га не покушава продати.","AI-gile је мали, лични пројекат, а не компанија. Рич је хтео да води неколико AI пројеката кодирања без отварања сваке апликације да провери стање, па су он и агенти направили таблу за то, а онда су помоћу ње направили остатак ње саме. У затвореној је пре-алфи, што значи да ради, углавном, за шачицу пријатеља. Нема странице са ценама, билтена ни плана раста. Ако ти звучи корисно, можеш да затражиш да пробаш кад се мало више отвори."]},{"n":144,"texts":["AI-gile је канбан табла за једног човека и много AI агената. Ради на твом рачунару и потпуно је бесплатна. Додајеш пројекте, и сваки пројекат добија вођу и мали тим. Ћаскаш са вођом, помало као на Discordu, и описујеш идеју; вођа је претвара у картице и план, па чека да притиснеш Крени. Тим пролази кроз картице по приоритету, помоћу једноставног алата за командну линију направљеног за језичке моделе. Пре него што ти се нешто врати, AI тестер прати кораке у копији апликације и прилаже снимак екрана. Готов посао стиже у твоју гомилу са измењеним фајловима и разликом. Прихватиш га, или оставиш коментар па се тим пробуди и покуша поново. Само ти можеш да преместиш картицу у Готово.","Отприлике један дан са AI-gile. Увече оставиш пар коментара: ово дугме је на погрешном месту, она листа треба да буде сортирана, може ли тамни режим. Одеш на спавање. Агенти прочитају коментаре, направе измене, тестирају их и врате ти их. Ако се Треба урадити испразни, ноћна стража га допуни из бекклога картицама којима не треба твој одговор. Ујутру те чека једна кратка гомила: пар питања и неколико ствари за пробу, свака са корацима које може да прати и поспана особа и са снимком екрана како ради. Кликнеш, прихватиш добре и вратиш остале. Бројач токена показује колико је све то потрошило, а No Token Mode је ту за скромније недеље. Затим доручкујеш, а у томе агенти још не могу да помогну.","Прво, шта AI-gile није. Није стартап, није на продају и нико не скупља твоје податке. То је бесплатна табла која ради на твом рачунару, без налога, без трагача и без колачића. А шта јесте: једно уредно место да видиш све своје AI пројекте кодирања одједном, са тимом агената који раде картице и тобом који доносиш одлуке. Спаја сродне картице, поправља збркане наслове и пази колико код остаје сажет. Говори око 120 језика, од холандског и фламанског до гусарског и клингонског. Пријатељи могу да пишу једни другима, приватно и шифровано. Направили су га Рич и велики број стрпљивих агената, углавном користећи њега самог. У затвореној је пре-алфи, па је на местима груб. Ако звучи забавно, лепо питај и можда уђеш раније."]}],"quips":{"1":"Једна реч. Смело. Можда превише смело.","3":"Три речи. Већ поштеније од већине страница производа.","8":"Осам речи. И даље краће од стендапа.","21":"Дужине су, успут, story points. Наравно да јесу.","55":"Педесет пет речи. Две картице су завршене док си ово читао.","144":"То је она дуга. Не постоји 233. Агенти су отишли на спавање."}},"timeline":{"first-idea.name":"Прва идеја","first-idea.line":"Сасвим први разговор, пре него што је постојао иједан ред кода.","first-board.name":"Прва табла","first-board.line":"Табла која прати сопствену изградњу: картице, колоне, превлачење, пројекти.","team-roles.name":"Тим и улоге","team-roles.line":"Профили агената, шаблони тимова, простори и ко шта ради.","install.name":"Инсталација и издања","install.line":"Зип који пријатељ може да инсталира, самоажурирање, канали и повратак на старо.","usage-saver.name":"Штедња потрошње","usage-saver.line":"Мери колико коштају покретања, држи код сажетим, чува твоје ограничење.","friends.name":"Пријатељи и дељење","friends.line":"Приватне поруке, прикривени релеј, позивнице, улоге и дељени пројекти.","languages.name":"Језици","languages.line":"Сваки текст на екрану у језичком фајлу, прво холандски и фламански.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер прво проверава сваку предају и показује шта је видео.","website.name":"Веб-сајт","website.line":"aigile.lol, тизер и ова временска линија.","streaming.name":"Ћаскање и стриминг","streaming.line":"Discord, Twitch, OBS, стример режим, GIF-ови и емоџији.","no-ai.name":"Издање без AI","no-ai.line":"Табла за људе који кодирају без AI, и јавне табле.","night-watch.name":"Ноћна стража","night-watch.line":"Чувар и Scrum Master држе тимове на задатку док ти спаваш.","p-more.name":"Све остало","p-more.line":"Мање идеје које чекају на ред.","p-android.name":"Телефон и Android","p-android.line":"Допри до табле са телефона, а затим изворна Android апликација.","p-release.name":"Алфа и даље","p-release.line":"Затворена алфа, живи сајт, па бета.","p-languages.name":"Још језика","p-languages.line":"Више од сто језика и режим уроњења за оне који уче.","p-engines.name":"Још AI мотора","p-engines.line":"Изабери Claude, Codex или Gemini за сваког агента.","p-pro.name":"Професионална пракса","p-pro.line":"Ознаке ризика, капије за спајање, картице за инциденте и заштитне ограде.","p-self.name":"Брига о теби","p-self.line":"Режим уморног, подсетници за бригу о себи и 4:20.","p-servers.name":"Сервери и раст","p-servers.line":"Глобална подешавања сервера, улоге и планирање раста.","p-livestream.name":"Додаци за стриминг","p-livestream.line":"Twitch ћаскање, прилагођени емоџији и јавни приказ уживо."}};
